from pathlib import Path
import html, json, numpy as np, pandas as pd
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'mockups'; OUT.mkdir(exist_ok=True,parents=True)
df=pd.read_csv(ROOT/'sample_data'/'beijing-demo.csv')
# Offline calculations solely for clearly labeled mockup sample visualization.
df['ts']=pd.to_datetime(df['timestamp'],utc=True)
df['day']=pd.to_datetime(df['timestamp'].str.slice(0,10))
df['zscore']=df.groupby('sensorId')['value'].transform(lambda x:(x-x.mean())/x.std(ddof=0))
flags=df[df.zscore.abs()>3].sort_values('zscore',ascending=False).reset_index(drop=True)
colors=['#087E8B','#2463D4','#E1A04A']; stations=['Nongzhanguan','Guanyuan','Tiantan']

def h(s):return html.escape(str(s))
def chart_line(data,width=860,height=300,colors=colors,ymax=None,legend=True):
    padL=50;padT=18;padB=42;padR=16
    values=[float(x) for r in data for x in r[1] if x is not None]
    ymax = float(ymax or max(100,round(max(values)*1.18/50)*50))
    innerW=width-padL-padR;innerH=height-padT-padB
    s=[f'<svg class="chart-svg" viewBox="0 0 {width} {height}" role="img" aria-label="Biểu đồ PM2.5 minh họa từ dữ liệu CSV">']
    for yt in [0,.25,.5,.75,1]:
        y=padT+innerH*(1-yt); v=int(round(yt*ymax))
        s.append(f'<line x1="{padL}" y1="{y:.1f}" x2="{width-padR}" y2="{y:.1f}" stroke="#E6ECF2"/>')
        s.append(f'<text x="{padL-14}" y="{y+4:.1f}" text-anchor="end" font-size="12" fill="#77889B">{v}</text>')
    n=max(len(r[1]) for r in data)
    for j,(name,vals) in enumerate(data):
        coords=[]
        for i,v in enumerate(vals):
            if v is None:continue
            x=padL+i/max(1,n-1)*innerW;y=padT+innerH*(1-min(v/ymax,1));coords.append((x,y))
        if not coords:continue
        d=' '.join(('M' if k==0 else 'L')+f'{x:.1f},{y:.1f}' for k,(x,y) in enumerate(coords))
        col=colors[j%len(colors)]
        s.append(f'<path d="{d}" fill="none" stroke="{col}" stroke-width="2.8" stroke-linejoin="round" stroke-linecap="round"/>')
    labels=['01/03','07/03','13/03','19/03','25/03','31/03']
    for i,t in enumerate(labels):
        x=padL+i/(len(labels)-1)*innerW
        s.append(f'<text x="{x:.1f}" y="{height-15}" text-anchor="middle" font-size="12" fill="#77889B">{t}</text>')
    s.append('</svg>')
    return ''.join(s)

daily=[]
for station in stations:
    series=df[df.sensorId==station].groupby('day')['value'].mean().reindex(pd.date_range('2015-03-01','2015-03-31'))
    daily.append((station,[None if pd.isna(v) else float(v) for v in series]))
plot=chart_line(daily,width=886,height=310,ymax=350)

navs=['Data Exploration','Visualization','Analysis','Anomalies']

